###############################################################################
#
#   Chevalley polytopes for G_2: both maximal parabolics and the Borel.
#
#   In this construction the parabolic is determined by the weight: P is the
#   stabiliser of the highest weight line of V_varpi, so W_P is generated by
#   the s_i with <varpi, alpha_i^vee> = 0.  Hence for G_2, in Bourbaki
#   labelling (alpha_1 short, alpha_2 long):
#
#       varpi = (a, 0), a > 0   ->  W_P = <s_2>,  X = G_2/P_1, dim X = 5
#                                   (the 5-dimensional quadric Q^5 for a = 1)
#       varpi = (0, b), b > 0   ->  W_P = <s_1>,  X = G_2/P_2, dim X = 5
#                                   (the adjoint Grassmannian, Appendix A.4)
#       varpi = (a, b), a,b > 0 ->  W_P = 1,      X = G_2/B,   dim X = 6
#                                   (the full flag variety)
#
#   G_2 has no commuting pair of simple reflections, so w^P has exactly one
#   reduced expression in the two maximal-parabolic cases and exactly two for
#   the Borel (the two alternating words of length 6).
#
#   Run with:   julia g2_chevalley_study.jl [outdir]
#
###############################################################################

using TropicalCensus
using Oscar

const OUTDIR = length(ARGS) >= 1 ? ARGS[1] : data_path("chevalley")
mkpath(OUTDIR)

const WEIGHTS = [
  [1, 0], [0, 1], [1, 1],
  [2, 0], [0, 2], [2, 1], [1, 2], [2, 2],
  [3, 0], [0, 3], [3, 1], [1, 3],
]

R = root_system(:G, 2)
W = weyl_group(R)

space_of(varpi) = varpi[1] > 0 && varpi[2] > 0 ? "G_2/B  " :
                  varpi[1] > 0 ? "G_2/P_1" : "G_2/P_2"

println("Chevalley polytopes for G_2\n")
println(rpad("varpi", 8), rpad("X", 9), rpad("dimX", 6), rpad("dimV", 7),
  rpad("word", 16), rpad("vol", 8), rpad("degX", 8), rpad("NObody", 8),
  rpad("verts", 7), rpad("latpts", 8), rpad("IDP", 6), "decomp")
println("-"^100)

results = []
for varpi in WEIGHTS
  wP = minimal_coset_representative(W, parabolic_indices(varpi))
  words = all_paper_words(wP; up_to_commutation=true)
  d, deg = degree_of_embedding(R, varpi)
  for w in words
    D = chevalley_data(:G, 2, varpi; word=w)
    P = chevalley_polytope(D)
    vol = normalised_volume_of(P)
    idp = has_idp(P)
    dec = check_decomposition(D)
    save_chevalley_polytope(D, OUTDIR)
    push!(results, (varpi=varpi, word=w, vol=vol, deg=deg, idp=idp, dec=dec.found))
    println(rpad(string(varpi), 8), rpad(space_of(varpi), 9), rpad(d, 6),
      rpad(dim(D.V), 7), rpad(join(w, ""), 16), rpad(vol, 8), rpad(deg, 8),
      rpad(vol == deg ? "yes" : "NO", 8), rpad(n_vertices(P), 7),
      rpad(length(lattice_points(P)), 8), rpad(idp ? "yes" : "no", 6),
      dec.found ? "yes" : "NO")
  end
end

println("\n", "-"^100)
println("Newton-Okounkov (vol == deg) in ", count(r -> r.vol == r.deg, results),
  " of ", length(results), " cases")
println("integer decomposition property in ", count(r -> r.idp, results),
  " of ", length(results), " cases")
println("Minkowski decomposition found in ", count(r -> r.dec, results),
  " of ", length(results), " cases")
